css_snippet:
a {
  color: #3366cc;
  text-decoration: underline;
  text-decoration-color: #6699ff; /* Custom color for better brand integration */
  text-decoration-thickness: 0.08em; /* Subtle thickness for elegance */
  text-underline-offset: 0.18em; /* Lifts the underline above descenders */
  transition: text-decoration-color 0.2s ease;
}
a:hover {
  text-decoration-color: #3366cc;
}
